/* Smart Cash v1.0 — electronic audit + analytics + AI. Rules run locally. AI gets ONLY anonymised aggregates, through your own proxy (server/worker.js): no API key ever lives in the browser. */
(function(){
const SC = window.SC, H = SC.h, V = SC.VIEWS, UI = SC.UI, t = SC.t, esc = SC.esc, ic = H.ic, fmt = SC.fmt, CFG = window.SC_CONFIG || {};
Object.assign(SCI18N.en,{in_title:"Audit & insights",in_row:"Audit & insights",in_row_hint:"Checks, analytics and AI suggestions",in_integrity:"Integrity",in_chain_ok:"Audit log chain verified ({n} sealed)",in_chain_bad:"Audit log was altered near entry {n}",in_seal_ok:"Approved records match their seals",in_seal_bad:"{n} approved record(s) changed after approval",in_findings:"Findings",in_none:"No issues found",in_kpi:"Overview",in_total:"Total spend",in_count:"Records",in_avg:"Average",in_cat:"By category",in_br:"By branch",in_mo:"By month",in_ai:"AI analysis",in_ai_run:"Run AI analysis",in_ai_hint:"Sends only anonymised totals (no names, phones or photos) to your AI proxy.",in_ai_off:"AI proxy not configured. Local audit above works fully. See docs/AI_SETUP.md.",in_ai_busy:"Analysing…",in_ai_err:"AI error: {m}",in_in:"Income",in_out:"Expenses",in_net:"Net",
 f_dup:"Possible duplicate",f_vat:"VAT does not match 15%",f_split:"Possible split purchases",f_self:"Approved by the same person who captured it",f_out:"Unusually large for its category",f_night:"Captured at night",f_photo:"Approved without a photo",f_round:"Many round amounts",f_over:"Spending jumped vs previous month",s_high:"High",s_med:"Medium",s_low:"Low"});
Object.assign(SCI18N.ar,{in_title:"التدقيق والتحليل",in_row:"التدقيق والتحليل",in_row_hint:"فحوصات وتحليلات واقتراحات بالذكاء الاصطناعي",in_integrity:"سلامة البيانات",in_chain_ok:"سلسلة سجل التدقيق سليمة ({n} مختوم)",in_chain_bad:"تم العبث بسجل التدقيق قرب السجل {n}",in_seal_ok:"السجلات المعتمدة مطابقة لأختامها",in_seal_bad:"{n} سجل معتمد تغيّر بعد الاعتماد",in_findings:"الملاحظات",in_none:"لا توجد ملاحظات",in_kpi:"نظرة عامة",in_total:"إجمالي الصرف",in_count:"عدد السجلات",in_avg:"المتوسط",in_cat:"حسب التصنيف",in_br:"حسب الفرع",in_mo:"حسب الشهر",in_ai:"تحليل الذكاء الاصطناعي",in_ai_run:"شغّل التحليل بالذكاء الاصطناعي",in_ai_hint:"يرسل إجماليات مجهولة فقط (بلا أسماء أو جوالات أو صور) إلى وسيط الذكاء الاصطناعي الخاص بك.",in_ai_off:"وسيط الذكاء الاصطناعي غير مُهيأ. التدقيق المحلي أعلاه يعمل بالكامل. راجع docs/AI_SETUP.md.",in_ai_busy:"جارٍ التحليل…",in_ai_err:"خطأ الذكاء الاصطناعي: {m}",in_in:"الدخل",in_out:"المصروفات",in_net:"الصافي",
 f_dup:"احتمال تكرار فاتورة",f_vat:"الضريبة لا تطابق 15%",f_split:"احتمال تجزئة مشتريات",f_self:"اعتمدها نفس من صوّرها",f_out:"مبلغ كبير بشكل غير معتاد لتصنيفه",f_night:"صُوّرت ليلًا",f_photo:"اعتُمدت بدون صورة",f_round:"مبالغ مستديرة كثيرة",f_over:"قفزة في الصرف مقارنة بالشهر السابق",s_high:"عالية",s_med:"متوسطة",s_low:"منخفضة"});
const day = d => String(d).slice(0,10), mon = d => String(d).slice(0,7), sum = a => a.reduce((s,x)=>s+x,0);
const sd = a => { const m = sum(a)/a.length; return Math.sqrt(sum(a.map(x=>(x-m)**2))/a.length) };
/* ---------- local rule engine ---------- */
SC.auditRules = (invs) => { const F = [], add = (rule, sev, ids) => ids.length && F.push({rule, sev, ids:[...new Set(ids)]});
  const live = invs.filter(i => i.status !== "rejected" && i.status !== "withdrawn");
  const seen = {}; live.forEach(i => { const k = [i.sup, i.total, day(i.date)].join("|"), k2 = i.invNo ? [i.sup, i.invNo].join("|") : null; (seen[k] = seen[k] || []).push(i.id); if(k2) (seen[k2] = seen[k2] || []).push(i.id) });
  add("f_dup","high", Object.values(seen).filter(a => a.length > 1).flat());
  add("f_vat","high", live.filter(i => String(i.kind||"").startsWith("tax") && i.total > 0 && Math.abs(i.vat - i.total*15/115) > 0.06).map(i=>i.id));
  const g = {}; live.forEach(i => { const k = [i.by, i.sup, day(i.date)].join("|"); (g[k] = g[k] || []).push(i.id) });
  add("f_split","med", Object.values(g).filter(a => a.length >= 3).flat());
  add("f_self","high", live.filter(i => i.status==="approved" && (i.hist||[]).some(h => /approve/.test(h.ev) && h.by && h.by===i.by)).map(i=>i.id));
  const byCat = {}; live.forEach(i => (byCat[i.cat] = byCat[i.cat] || []).push(i));
  add("f_out","med", Object.values(byCat).filter(a => a.length >= 6).flatMap(a => { const v = a.map(x=>x.total), m = sum(v)/v.length, s = sd(v); return s > 0 ? a.filter(x => x.total > m + 3*s).map(x=>x.id) : [] }));
  add("f_night","low", live.filter(i => { const h = new Date(i.date).getHours(); return h >= 0 && h < 4 }).map(i=>i.id));
  add("f_photo","low", live.filter(i => i.status==="approved" && !i.img && i.src !== "qr").map(i=>i.id));
  const rnd = live.filter(i => i.total >= 500 && i.total % 100 === 0); if(live.length >= 10 && rnd.length / live.length > .25) add("f_round","low", rnd.map(i=>i.id));
  const mo = {}; live.forEach(i => { mo[mon(i.date)] = (mo[mon(i.date)]||0) + i.total }); const ks = Object.keys(mo).sort(); if(ks.length >= 2){ const a = mo[ks.at(-2)], b = mo[ks.at(-1)]; if(a > 0 && b > a*1.6) add("f_over","med", live.filter(i => mon(i.date)===ks.at(-1)).map(i=>i.id).slice(0,1)) }
  const o = {high:0, med:1, low:2}; return F.sort((x,y)=>o[x.sev]-o[y.sev]) };
SC.summary = (invs) => { const live = invs.filter(i => i.status==="approved" || i.status==="review"), by = (f) => { const m = {}; live.forEach(i => { const k = f(i); m[k] = (m[k]||0) + i.total }); return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,10) };
  const sup = {}; live.forEach(i => { const k = i.sup || "?"; (sup[k] = sup[k] || {n:0, total:0}); sup[k].n++; sup[k].total += i.total });
  return {n:live.length, total:+sum(live.map(i=>i.total)).toFixed(2), cat:by(i=>i.cat), month:by(i=>mon(i.date)).sort((a,b)=>a[0]<b[0]?-1:1), branch:SC.S.plan==="enterprise" ? by(i=>i.branch||"-").filter(x=>x[0]!=="-") : [],
    suppliers:Object.values(sup).sort((a,b)=>b.total-a.total).slice(0,8).map((x,k)=>({id:"S"+(k+1), n:x.n, total:+x.total.toFixed(2)}))} };
/* ---------- AI through your proxy ---------- */
SC.aiConfigured = () => !!CFG.aiEndpoint;
SC.aiAnalyze = async (payload) => { const ctl = new AbortController(), to = setTimeout(() => ctl.abort(), 45000);
  try{ const r = await fetch(CFG.aiEndpoint, {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({lang:SC.ui.lang, currency:SC.cur(), plan:SC.S.plan, ...payload}), signal:ctl.signal, credentials:"omit"});
    if(!r.ok) throw new Error(r.status === 429 ? "rate limit" : "HTTP " + r.status); const j = await r.json(); if(typeof j.text !== "string") throw new Error("bad reply"); SC.audit("au_ai"); SC.save(); return j.text.slice(0, 6000) } finally { clearTimeout(to) } };
const md = tx => esc(tx).split(/\n{2,}/).map(p => `<p class="t2" style="margin:0 0 10px;white-space:pre-line">${p.replace(/\*\*(.+?)\*\*/g,"<b>$1</b>")}</p>`).join("");
const bars = (rows, total) => rows.map(([k, v]) => `<div class="row"><div class="grow"><div class="t1">${esc(k)}</div><div style="height:6px;border-radius:6px;background:var(--line,rgba(127,127,127,.18));margin-top:6px"><div style="height:100%;width:${total ? Math.max(3, v/total*100) : 0}%;border-radius:6px;background:var(--accent)"></div></div></div><span class="num t1">${fmt(v)}</span></div>`).join("");
const sevPill = s => `<span class="pill ${s==="high"?"p-rejected":s==="med"?"p-review":"p-approved"}">${t("s_"+s)}</span>`;
V.insights = () => { const personal = !!SC.P(), res = UI.insRes || {}, busy = UI.busy === "ai";
  if(personal){ const c = (SC.P().cash||[]), inn = sum(c.filter(x=>x.dir==="in").map(x=>x.amt)), out = sum(c.filter(x=>x.dir!=="in").map(x=>x.amt));
    return `<div class="page">${H.nav(t("in_title"))}<div class="glass list wpad"><div class="row"><div class="grow t1">${t("in_in")}</div><span class="num t1">${fmt(inn)}</span></div><div class="row"><div class="grow t1">${t("in_out")}</div><span class="num t1">${fmt(out)}</span></div><div class="row"><div class="grow t1">${t("in_net")}</div><span class="num t1">${fmt(inn-out)}</span></div></div>${aiBlock(busy, res, {cash:c.slice(0,200).map(x=>({d:x.dir, a:x.amt, m:String(x.t).slice(0,7)}))})}</div>` }
  const invs = SC.can("export_all") || SC.can("audit") || SC.can("reports") ? SC.S.invoices : SC.visibleInvoices(), sm = SC.summary(invs), F = SC.auditRules(invs), chain = res.chain, tam = res.tam;
  const integ = !chain ? `<button class="row" data-act="insverify"><span class="ico">${ic("shield",20)}</span><div class="grow"><div class="t1">${t("in_integrity")}</div><div class="t2">${t("in_ai_busy").replace("…","")}…</div></div></button>`
   : `<div class="row"><span class="ico">${ic("shield",20)}</span><div class="grow"><div class="t1">${chain.ok ? t("in_chain_ok",{n:chain.sealed}) : t("in_chain_bad",{n:chain.bad})}</div><div class="t2">${tam.length ? t("in_seal_bad",{n:tam.length}) : t("in_seal_ok")}</div></div>${chain.ok && !tam.length ? `<span class="pill p-approved">✓</span>` : `<span class="pill p-rejected">!</span>`}</div>`;
  return `<div class="page">${H.nav(t("in_title"))}<div class="sec-h"><span class="h2">${t("in_integrity")}</span></div><div class="glass list">${integ}</div>
  <div class="sec-h"><span class="h2">${t("in_findings")}</span></div><div class="glass list">${F.length ? F.map(f => `<div class="row"><div class="grow"><div class="t1">${t(f.rule)}</div><div class="t2 num">${f.ids.slice(0,4).map(esc).join(" · ")}${f.ids.length>4?" +"+(f.ids.length-4):""}</div></div>${sevPill(f.sev)}</div>`).join("") : `<div class="row"><div class="grow t2">${t("in_none")}</div></div>`}</div>
  <div class="sec-h"><span class="h2">${t("in_kpi")}</span></div><div class="glass list"><div class="row"><div class="grow t1">${t("in_total")}</div><span class="num t1">${fmt(sm.total)} ${SC.cur()}</span></div><div class="row"><div class="grow t1">${t("in_count")}</div><span class="num t1">${sm.n}</span></div><div class="row"><div class="grow t1">${t("in_avg")}</div><span class="num t1">${fmt(sm.n ? sm.total/sm.n : 0)}</span></div></div>
  ${sm.cat.length ? `<div class="sec-h"><span class="h2">${t("in_cat")}</span></div><div class="glass list">${bars(sm.cat.slice(0,6).map(([k,v])=>[(SCI18N[SC.ui.lang]&&SCI18N[SC.ui.lang]["cat_"+k]) ? t("cat_"+k) : k, v]), sm.total)}</div>` : ""}
  ${sm.branch.length ? `<div class="sec-h"><span class="h2">${t("in_br")}</span></div><div class="glass list">${bars(sm.branch.map(([k,v])=>[SC.branchName(k)||k, v]), sm.total)}</div>` : ""}
  ${sm.month.length ? `<div class="sec-h"><span class="h2">${t("in_mo")}</span></div><div class="glass list">${bars(sm.month, Math.max(...sm.month.map(x=>x[1])))}</div>` : ""}
  ${aiBlock(busy, res, {summary:sm, findings:F.map(f=>({rule:f.rule, sev:f.sev, n:f.ids.length}))})}</div>` };
function aiBlock(busy, res, payload){ UI.insPayload = payload; return `<div class="sec-h"><span class="h2">${t("in_ai")}</span></div><div class="glass list wpad">${SC.aiConfigured()
  ? `<div class="row"><div class="grow t2">${t("in_ai_hint")}</div></div><div class="row"><button class="btn btn-accent" data-act="insai" ${busy?"disabled":""}>${busy ? t("in_ai_busy") : t("in_ai_run")}</button></div>${res.ai ? `<div class="row"><div class="grow">${md(res.ai)}</div></div>` : ""}${res.err ? `<div class="row"><div class="grow t2" style="color:var(--neg)">${esc(res.err)}</div></div>` : ""}`
  : `<div class="row"><div class="grow t2">${t("in_ai_off")}</div></div>`}</div>` }
/* ---------- entry points ---------- */
const baseMe = V.me; V.me = () => { let h = baseMe(); const i = h.lastIndexOf('<div class="spacer">'); const row = `<div class="glass list wpad"><button class="row" data-act="go" data-v="insights"><span class="ico">${ic("shield",20)}</span><div class="grow"><div class="t1">${t("in_row")}</div><div class="t2">${t("in_row_hint")}</div></div></button></div>`; return SC.me() ? (i>=0 ? h.slice(0,i)+row+h.slice(i) : h+row) : h };
document.addEventListener("click", async e => { const b = e.target.closest("[data-act]"); if(!b) return; const a = b.dataset.act;
  if(a==="insverify"){ UI.insRes = {chain:await SC.auditVerify(), tam:await SC.invoiceTampered()}; SC.render(true) }
  else if(a==="insai"){ UI.busy = "ai"; UI.insRes = {...(UI.insRes||{}), err:null}; SC.render(true); try{ UI.insRes.ai = await SC.aiAnalyze(UI.insPayload || {}) }catch(x){ UI.insRes.err = t("in_ai_err",{m:String(x.message||x).slice(0,80)}) } UI.busy = null; SC.render(true) } }, true);
const baseGo = SC.afterRender; SC.afterRender = function(){ if(baseGo) baseGo.apply(this, arguments); if(UI.screen==="insights" && !(UI.insRes && UI.insRes.chain) && !UI.insBusy){ UI.insBusy = 1; Promise.all([SC.auditVerify(), SC.invoiceTampered()]).then(([c, tm]) => { UI.insRes = {...(UI.insRes||{}), chain:c, tam:tm}; UI.insBusy = 0; if(UI.screen==="insights") SC.render(true) }) } };
})();
